// Worker entry point: hands every web request to Next.js (OpenNext) and adds a scheduler for the Cron Trigger.
// @ts-expect-error: this file is generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  /** Cron Trigger (wrangler.jsonc → triggers.crons): calls the /api/cron route itself so both share one code path. */
  async scheduled(_event: ScheduledController, env: CloudflareEnv & { CRON_SECRET?: string }, ctx: ExecutionContext) {
    const req = new Request("https://servicebook.internal/api/cron", {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(handler.fetch(req, env, ctx).then(async (r: Response) => console.log("[cron]", r.status, await r.text())));
  },
} satisfies ExportedHandler<CloudflareEnv>;

// Durable Objects generated by OpenNext (if any) must be exported from the entry file
// @ts-expect-error: file do build sinh ra
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
